function BinanceProofSummary({ locale, binance }: { locale: Locale; binance: ReturnType<typeof useIntegrationEvidence>["binance"] }) {
  const status = binance?.status ?? "UNAVAILABLE";
  const endpoint = binance?.requests?.length ? binance.requests.map((item) => item.endpoint).join(" · ") : binance?.endpoints?.join(" · ") ?? "UNAVAILABLE";
  const result = binance?.quote ? `${binance.quote.bidPrice} bid · ${binance.quote.askPrice} ask` : binance?.error ? `${binance.error.kind}: ${binance.error.message}` : "UNAVAILABLE";
  const freshness = binance?.quote ? t(locale, "Authenticated HTTP success is verified. The provider does not supply a source timestamp, so price freshness remains CACHED.", "Se verificó el éxito HTTP autenticado. El proveedor no entrega timestamp de origen, por lo que la frescura del precio permanece CACHED.") : t(locale, "Freshness cannot be established without a successful quote.", "La frescura no puede establecerse sin una cotización exitosa.");
  return <article className="binance-proof"><header><div><span>BINANCE STOCKS TRADING MARKET DATA</span><strong>{t(locale, "Transport proof and price freshness are separate", "La prueba de transporte y la frescura del precio están separadas")}</strong></div><StatusBadge status={status} /></header><dl><Meta label={t(locale, "Query", "Consulta")} value={endpoint} /><Meta label={t(locale, "Requested asset", "Activo solicitado")} value={binance?.symbol ?? "UNAVAILABLE"} /><Meta label={t(locale, "Result", "Resultado")} value={result} /><Meta label="HTTP" value={binance?.responseStatus?.toString() ?? "UNAVAILABLE"} /><Meta label={t(locale, "Ghost receipt time", "Hora de recepción de Ghost")} value={dateTime(binance?.observedAt, locale)} /><Meta label={t(locale, "Provider source time", "Hora de origen del proveedor")} value={t(locale, "Not supplied", "No proporcionada")} /><Meta label={t(locale, "Latency", "Latencia")} value={binance?.latencyMs == null ? "UNAVAILABLE" : `${binance.latencyMs} ms`} /><Meta label="Request ID" value={binance?.providerRequestId ?? binance?.requestId ?? "UNAVAILABLE"} /></dl><p><ShieldCheck />{freshness}</p></article>;
}

function RwaProofSummary({ locale, rwa }: { locale: Locale; rwa: ReturnType<typeof useIntegrationEvidence>["rwa"] }) {
  const status = rwa?.status ?? "UNAVAILABLE";
  const asset = rwa?.assets[0];
  const endpoints = rwa?.requests.length ? rwa.requests.map((item) => new URL(item.endpoint).pathname.split("/").at(-1)).join(" · ") : "search · price · underlying-profile · underlying-market";
  const issueSummary = rwa?.issues?.map((issue) => `${issue.platformId}/${issue.stage}: ${issue.kind}`).join(" · ");
  const providerProof = rwa?.requests[0];
  return <article className="binance-proof rwa-proof"><header><div><span>BINANCE WEB3 RWA DATA API</span><strong>{t(locale, "Official signed Web3 module", "Módulo Web3 oficial con firma")}</strong></div><StatusBadge status={status} /></header><dl><Meta label={t(locale, "Authentication", "Autenticación")} value={rwa?.credentialState === "CONFIGURED" ? "HMAC-SHA256 · SERVER ONLY" : t(locale, "Web3 credentials missing", "Faltan credenciales Web3")} /><Meta label={t(locale, "Endpoints", "Endpoints")} value={endpoints} /><Meta label={t(locale, "Platforms found", "Plataformas encontradas")} value={rwa?.assets.length ? rwa.assets.map((item) => item.platformId).join(" · ") : "UNAVAILABLE"} /><Meta label={t(locale, "Token price", "Precio tokenizado")} value={money(asset?.tokenPrice)} /><Meta label={t(locale, "RWA reference", "Referencia RWA")} value={money(asset?.referencePrice)} /><Meta label={t(locale, "Market status", "Estado del mercado")} value={asset?.marketStatus ?? "UNAVAILABLE"} /><Meta label="HTTP" value={rwa?.responseStatus?.toString() ?? "—"} /><Meta label={t(locale, "Business code", "Código de negocio")} value={providerProof?.businessCode?.toString() ?? "—"} /><Meta label={t(locale, "Provider message", "Mensaje del proveedor")} value={providerProof?.providerMessage ?? "—"} /><Meta label="Request ID" value={rwa?.requestId ?? "UNAVAILABLE"} /></dl>{rwa?.error ? <p><TriangleAlert />{rwa.error.kind}: {rwa.error.message}</p> : issueSummary ? <p><TriangleAlert />{t(locale, "Partial provider response", "Respuesta parcial del proveedor")}: {issueSummary}</p> : <p><ShieldCheck />{t(locale, "Token and reference prices keep their own freshness label and do not bypass Ghost's liquidity gates.", "Los precios tokenizado y de referencia conservan su propia etiqueta de frescura y no evitan los controles de liquidez de Ghost.")}</p>}</article>;
}

function WalletSkillProofSummary({ locale, walletSkill }: { locale: Locale; walletSkill: ReturnType<typeof useIntegrationEvidence>["walletSkill"] }) {
  const asset = walletSkill?.asset;
  return <article className="binance-proof wallet-skill-proof"><header><div><span>BINANCE WALLET SKILL · TOKENIZED SECURITIES INFO</span><strong>{t(locale, "Official public read-only Skill", "Skill oficial pública y de solo lectura")}</strong></div><StatusBadge status={walletSkill?.status ?? "UNAVAILABLE"} /></header><dl><Meta label={t(locale, "Skill", "Skill")} value={`binance-tokenized-securities-info · v${walletSkill?.skillVersion ?? "1.1"}`} /><Meta label={t(locale, "Issuer / token", "Emisor / token")} value={asset ? `${asset.issuer} · ${asset.tokenSymbol}` : "UNAVAILABLE"} /><Meta label={t(locale, "Network", "Red")} value={asset ? `${asset.network} · Chain ${asset.chainId}` : "UNAVAILABLE"} /><Meta label={t(locale, "Contract", "Contrato")} value={asset?.contractAddress ?? "UNAVAILABLE"} /><Meta label={t(locale, "Token price", "Precio token")} value={money(asset?.tokenPriceUsd)} /><Meta label={t(locale, "Shares multiplier", "Multiplicador de acciones")} value={asset ? asset.multiplier.toString() : "UNAVAILABLE"} /><Meta label={t(locale, "Normalized per share", "Normalizado por acción")} value={money(asset?.normalizedPerShareUsd)} /><Meta label={t(locale, "Price freshness", "Frescura del precio")} value={asset?.priceStatus ?? "UNAVAILABLE"} /><Meta label="HTTP / BUSINESS" value={walletSkill?.requests.length ? walletSkill.requests.map((item) => `${item.statusCode}/${item.businessCode ?? "—"}`).join(" · ") : "UNAVAILABLE"} /><Meta label="Request ID" value={walletSkill?.requestId ?? "UNAVAILABLE"} /></dl>{asset ? <p><ShieldCheck />{t(locale, "Identity and normalization accepted. DEX liquidity remains missing, so this price does not enter Ghost Consensus.", "Identidad y normalización aceptadas. La liquidez DEX sigue faltante, por lo que este precio no entra en Ghost Consensus.")}</p> : <p><TriangleAlert />{walletSkill?.error?.message ?? "UNAVAILABLE"}</p>}</article>;
}

function TechnicalSnapshot({ locale, evidence, binance, rwa, walletSkill, live }: { locale: Locale; evidence: ReturnType<typeof useIntegrationEvidence>["evidence"]; binance: ReturnType<typeof useIntegrationEvidence>["binance"]; rwa: ReturnType<typeof useIntegrationEvidence>["rwa"]; walletSkill: ReturnType<typeof useIntegrationEvidence>["walletSkill"]; live: ReturnType<typeof useIntegrationEvidence>["live"] }) { return <details className="technical-disclosure pro-snapshot" open><summary><SlidersHorizontal />{t(locale, "Technical details", "Detalles técnicos")}<ChevronDown /></summary><div className="technical-grid"><Meta label="Network" value="BSC Mainnet · Chain ID 56" /><Meta label="xStocks contract" value={live?.registry?.contractAddress ?? evidence?.contractAddress ?? "UNAVAILABLE"} /><Meta label="Ondo contract" value={walletSkill?.asset?.contractAddress ?? rwa?.assets[0]?.tokenContractAddress ?? "UNAVAILABLE"} /><Meta label="ISIN" value={live?.registry?.isin ?? "UNAVAILABLE"} /><Meta label="Block" value={evidence?.blockNumber?.toLocaleString() ?? "UNAVAILABLE"} /><Meta label="Request ID" value={walletSkill?.requestId ?? rwa?.requestId ?? live?.requestId ?? "UNAVAILABLE"} /><Meta label="Latency" value={walletSkill?.latencyMs == null ? rwa?.latencyMs == null ? live?.latencyMs == null ? "UNAVAILABLE" : `${live.latencyMs} ms` : `${rwa.latencyMs} ms` : `${walletSkill.latencyMs} ms`} /><Meta label="Binance Stocks" value={binance?.error?.kind ?? binance?.status ?? "UNAVAILABLE"} /><Meta label="Signed Web3 RWA" value={rwa?.error?.kind ?? rwa?.status ?? "UNAVAILABLE"} /><Meta label="Wallet Skill" value={walletSkill?.error?.kind ?? walletSkill?.status ?? "UNAVAILABLE"} /></div></details>; }
function EducationalNote({ locale, text }: { locale: Locale; text: string }) { return <div className="educational-note"><BookOpen /><div><strong>{t(locale, "Why does this matter?", "¿Por qué importa?")}</strong><p>{text}</p></div></div>; }
function StepActions({ locale, onBack, onNext }: { locale: Locale; onBack: () => void; onNext: () => void }) { return <div className="step-actions"><button className="secondary-action" onClick={onBack}><ArrowLeft />{t(locale, "Back", "Atrás")}</button><button className="primary-action" onClick={onNext}>{t(locale, "Continue", "Continuar")}<ArrowRight /></button></div>; }
function StatusBadge({ status, label }: { status: DataState | string; label?: string }) { return <span className={`status-badge status-${status.toLowerCase()}`}><i />{label ?? status}</span>; }
function Metric({ label, value }: { label: string; value: string }) { return <div className="metric"><span>{label}</span><strong>{value}</strong></div>; }
function Meta({ label, value }: { label: string; value: string }) { return <div className="meta-item"><dt>{label}</dt><dd>{value}</dd></div>; }
function EvidenceBucket({ title, tone, items }: { title: string; tone: string; items: string[] }) { return <div className={`evidence-bucket ${tone}`}><strong>{title}</strong>{items.length ? items.map((item) => <p key={item}><i />{item}</p>) : <p><i />None</p>}</div>; }
function ScoreLesson({ name, copy }: { name: string; copy: string }) { return <div className="score-lesson"><strong>{name}</strong><p>{copy}</p></div>; }
function JudgeCard({ title, text }: { title: string; text: string }) { return <article><span>{title}</span><p>{text}</p></article>; }
function GhostGlyph() { return <span className="ghost-glyph" aria-hidden="true"><i /><i /></span>; }
function StateIcon({ status }: { status: DataState }) { if (status === "LIVE" || status === "CACHED") return <CheckCircle2 className="state-icon" />; if (status === "REJECTED") return <TriangleAlert className="state-icon" />; if (status === "ERROR") return <CircleX className="state-icon" />; return <CircleDashed className="state-icon" />; }
function MobileNav({ section, locale, onNavigate }: { section: Section; locale: Locale; onNavigate: (section: Section) => void }) { return <nav className="mobile-bottom-nav" aria-label={t(locale, "Mobile navigation", "Navegación móvil")}>{NAV.map((item) => { const Icon = item.icon; return <button key={item.id} className={section === item.id ? "active" : ""} onClick={() => onNavigate(item.id)}><Icon /><span>{locale === "en" ? item.en : item.es}</span></button>; })}</nav>; }
function chapterCopy(locale: Locale, chapter: number) { const en = ["The traditional reference stops updating.", "Three simulated venues remain active.", "Their prices begin to separate from the frozen reference.", "Ghost compares agreement, freshness, spread and liquidity.", "A controlled weak-market price tests the engine.", "Quality penalties lower the outlier’s influence.", "The next simulated traditional reference arrives.", "Ghost separates what worked from what remained unknown."]; const es = ["La referencia tradicional deja de actualizarse.", "Tres venues simulados permanecen activos.", "Sus precios comienzan a separarse de la referencia congelada.", "Ghost compara acuerdo, frescura, spread y liquidez.", "Un precio controlado de mercado débil pone a prueba el motor.", "Las penalizaciones de calidad reducen la influencia del outlier.", "Llega la siguiente referencia tradicional simulada.", "Ghost separa lo que funcionó de lo que quedó sin respuesta."]; return (locale === "en" ? en : es)[chapter]; }
